#quickstart.text:
object QuickStartMapping extends ValueMapping[IO] {

  // The data: an ordinary Scala value, with no Grackle dependencies.
  case class Book(id: Int, title: String, author: String)

  val books =
    List(
      Book(1, "The Left Hand of Darkness", "Ursula K. Le Guin"),
      Book(2, "Kindred", "Octavia E. Butler"),
      Book(3, "Hyperion", "Dan Simmons")
    )

  // The schema, validated at compile time by the `schema` interpolator.
  val schema =
    schema"""
      type Query {
        books: [Book!]!
        book(id: Int!): Book
      }
      type Book {
        id: Int!
        title: String!
        author: String!
      }
    """

  val QueryType = schema.ref("Query")
  val BookType  = schema.ref("Book")

  // The mapping: how each GraphQL field is served from the data.
  val typeMappings =
    List(
      ValueObjectMapping[Unit](
        tpe = QueryType,
        fieldMappings =
          List(
            ValueField("books", _ => books),
            ValueField("book", _ => books)
          )
      ),
      ValueObjectMapping[Book](
        tpe = BookType,
        fieldMappings =
          List(
            ValueField("id", _.id),
            ValueField("title", _.title),
            ValueField("author", _.author)
          )
      )
    )

  // The elaborator: turn `book(id: 2)` into a predicate that selects one book.
  override val selectElaborator =
    SelectElaborator {
      case (QueryType, "book", List(Binding("id", IntValue(id)))) =>
        Elab.transformChild(child => Unique(Filter(Eql(BookType / "id", Const(id)), child)))
    }
}

#model_types.text:
object Episode extends Enumeration {
  val NEWHOPE, EMPIRE, JEDI = Value
}

sealed trait Character {
  def id: String
  def name: Option[String]
  def appearsIn: Option[List[Episode.Value]]
  def friends: Option[List[String]]
}

object Character {
  implicit val cursorBuilder: CursorBuilder[Character] =
    deriveInterfaceCursorBuilder[Character](CharacterType)
}

case class Human(
    id: String,
    name: Option[String],
    appearsIn: Option[List[Episode.Value]],
    friends: Option[List[String]],
    homePlanet: Option[String]
) extends Character

object Human {
  implicit val cursorBuilder: CursorBuilder[Human] =
    deriveObjectCursorBuilder[Human](HumanType).transformField("friends")(resolveFriends)
}

case class Droid(
    id: String,
    name: Option[String],
    appearsIn: Option[List[Episode.Value]],
    friends: Option[List[String]],
    primaryFunction: Option[String]
) extends Character

object Droid {
  implicit val cursorBuilder: CursorBuilder[Droid] =
    deriveObjectCursorBuilder[Droid](DroidType).transformField("friends")(resolveFriends)
}

def resolveFriends(c: Character): Result[Option[List[Character]]] =
  c.friends match {
    case None => None.success
    case Some(ids) =>
      ids
        .traverse(id => characters.find(_.id == id).toResultOrError(s"Bad id '$id'"))
        .map(_.some)
  }

#elaborator.text:
override val selectElaborator = SelectElaborator {
  case (QueryType, "country", List(Binding("code", StringValue(code)))) =>
    Elab.transformChild { child =>
      Unique(Filter(Eql(CountryType / "code", Const(code)), child))
    }

  case (
        QueryType,
        "countries",
        List(
          Binding("maxPopulation", IntValue(max)),
          Binding("sortByPopulation", BooleanValue(sortByPop)),
          Binding("offset", IntValue(off)),
          Binding("limit", IntValue(lim))
        )
      ) =>
    def filter(query: Query): Query =
      if (max < 0) query
      else Filter(LtEql(CountryType / "population", Const(max)), query)

    def order(query: Query): Query =
      if (!sortByPop) query
      else
        OrderBy(
          OrderSelections(List(OrderSelection[Int](CountryType / "population"))),
          query
        )

    def offset(query: Query): Query =
      if (off < 1) query
      else Offset(off, query)

    def limit(query: Query): Query =
      if (lim < 0) query
      else Limit(lim, query)

    Elab.transformChild(child => limit(offset(order(filter(child)))))

  case (QueryType, "city", List(Binding("id", IntValue(id)))) =>
    Elab.transformChild(child => Unique(Filter(Eql(CityType / "id", Const(id)), child)))

  case (QueryType, "cities", List(Binding("namePattern", StringValue(namePattern)))) =>
    if (namePattern == "%")
      Elab.unit
    else
      Elab.transformChild { child =>
        Filter(Like(CityType / "name", namePattern, true), child)
      }

  case (CountryType, "numCities", List(Binding("namePattern", AbsentValue))) =>
    Elab.transformChild { _ => Count(Select("cities", Select("name"))) }

  case (CountryType, "numCities", List(Binding("namePattern", StringValue(namePattern)))) =>
    Elab.transformChild { _ =>
      Count(
        Select(
          "cities",
          Filter(Like(CityType / "name", namePattern, true), Select("name"))
        )
      )
    }
}

#ms_mapping.text:
// A single mutable cell of state shared by the query, mutation and subscription.
def mapping(ref: SignallingRef[IO, Int]): Mapping[IO] =
  new ValueMapping[IO] {

    val schema: Schema =
      schema"""
        type Query {
          get: Int!
        }
        type Mutation {
          put(n: Int): Int!
        }
        type Subscription {
          watch: Int!
        }
      """

    val QueryType        = schema.ref("Query")
    val MutationType     = schema.ref("Mutation")
    val SubscriptionType = schema.ref("Subscription")

    val typeMappings =
      List(
        // A query reads the current value.
        ObjectMapping(
          QueryType,
          List(
            RootEffect.computeCursor("get")((path, env) =>
              ref.get.map(n => Result(valueCursor(path, env, n))))
          )
        ),
        // A mutation runs an effect (here, a write) and returns a value to select over.
        ObjectMapping(
          MutationType,
          List(
            RootEffect.computeCursor("put")((path, env) =>
              env.get[Int]("n") match {
                case None    => Result.failure(s"Implementation error: `n: Int` not found in $env").pure[IO]
                case Some(n) => ref.set(n).map(_ => Result(valueCursor(path, env, n)))
              })
          )
        ),
        // A subscription is a stream of cursors, one per emitted value.
        ObjectMapping(
          SubscriptionType,
          List(
            RootStream.computeCursor("watch")((path, env) =>
              ref.discrete.map(n => Result(valueCursor(path, env, n))))
          )
        )
      )

    // Lift the `n` argument of `put` into the environment so the effect can read it.
    override val selectElaborator: SelectElaborator =
      SelectElaborator {
        case (MutationType, "put", List(Query.Binding("n", Value.IntValue(n)))) =>
          Elab.env("n" -> n)
      }
  }

#filter.text:
object FilterMapping extends ValueMapping[IO] {

  case class Item(label: String, tags: List[String])

  val items =
    List(
      Item("A", List("A")),
      Item("AB", List("A", "B")),
      Item("BC", List("B", "C")),
      Item("C", List("C"))
    )

  val schema =
    schema"""
      type Query {
        itemsByTag(tag: ID!): [Item!]!
        itemsByTagCount(count: Int!): [Item!]!
      }
      type Item {
        label: String!
        tags: [String!]!
        tagCount: Int!
      }
    """

  val QueryType = schema.ref("Query")
  val ItemType  = schema.ref("Item")

  val typeMappings =
    List(
      ValueObjectMapping[Unit](
        tpe = QueryType,
        fieldMappings =
          List(
            ValueField("itemsByTag", _ => items),
            ValueField("itemsByTagCount", _ => items)
          )
      ),
      ValueObjectMapping[Item](
        tpe = ItemType,
        fieldMappings =
          List(
            ValueField("label", _.label),
            ValueField("tags", _.tags),
            // `tagCount` has no backing field; it is computed from the cursor.
            CursorField("tagCount", tagCount)
          )
      )
    )

  def tagCount(c: Cursor): Result[Int] =
    c.fieldAs[List[String]]("tags").map(_.size)

  override val selectElaborator =
    SelectElaborator {
      // `Contains` tests membership of a list-valued field.
      case (QueryType, "itemsByTag", List(Binding("tag", IDValue(tag)))) =>
        Elab.transformChild(child => Filter(Contains(ItemType / "tags", Const(tag)), child))
      // `Eql` compares a (here computed) field against a constant.
      case (QueryType, "itemsByTagCount", List(Binding("count", IntValue(count)))) =>
        Elab.transformChild(child => Filter(Eql(ItemType / "tagCount", Const(count)), child))
    }
}

#fool_mk.text:
object FilterValue {
  def unapply(input: ObjectValue): Option[String] = {
    input.fields match {
      case List(("id", StringValue(id))) =>
        Some(id)
      case _ => None
    }
  }
}

def mkOffset(query: Query, limit: Value): Result[Query] =
  limit match {
    case AbsentValue | NullValue => query.success
    case IntValue(num) if num == 0 => query.success
    case IntValue(num) if num > 0 => Offset(num, query).success
    case IntValue(num) => Result.failure(s"Expected offset >= 0, found $num")
    case other => Result.failure(s"Expected offset >= 0, found $other")
  }

def mkLimit(query: Query, limit: Value): Result[Query] =
  limit match {
    case AbsentValue | NullValue => query.success
    case IntValue(num) if num > 0 => Limit(num, query).success
    case IntValue(num) => Result.failure(s"Expected limit > 0, found $num")
    case other => Result.failure(s"Expected limit > 0, found $other")
  }

def mkFilter(query: Query, tpe: Type, filter: Value): Result[Query] = {
  filter match {
    case AbsentValue | NullValue => query.success
    case FilterValue(id) => Filter(Eql(tpe / "id", Const(id)), query).success
    case _ => Result.failure(s"Expected filter value, found $filter")
  }
}

def mkOrderBy(query: Query, order: Value)(
    oss: ListOrder => List[OrderSelection[_]]): Result[Query] =
  order match {
    case AbsentValue | NullValue => query.success
    case OrderValue(o) =>
      oss(o) match {
        case Nil => query.success
        case oss => OrderBy(OrderSelections(oss), query).success
      }
    case _ => Result.failure(s"Expected sort value, found $order")
  }

#paging1.text:
abstract class PagingConfig(key: String, countAttr: String, orderTerm: Term[String]) {
  def setup(offset: Int, limit: Int): Elab[Unit] =
    Elab.env(key -> new PagingInfo(offset, limit))

  def elabItems = Elab.envE[PagingInfo](key).flatMap(_.elabItems)
  def elabTotal = Elab.envE[PagingInfo](key).flatMap(_.elabTotal)

  def genOffset(c: Cursor): Result[Int] = info(c, _.offset)
  def genLimit(c: Cursor): Result[Int] = info(c, _.limit)

  def info(c: Cursor, f: PagingInfo => Int): Result[Int] =
    c.env[PagingInfo](key).map(f).toResultOrError(s"Missing key '$key'")

  case class PagingInfo(offset: Int, limit: Int) {
    def elabItems: Elab[Unit] =
      Elab.transformChild { child =>
        FilterOrderByOffsetLimit(
          None,
          Some(List(OrderSelection(orderTerm, nullsLast = nullsHigh))),
          Some(offset),
          Some(limit),
          child)
      }

    def elabTotal: Elab[Unit] =
      Elab.transformChild(_ => Count(Select("items", Select(countAttr))))
  }
}

object CountryPaging extends PagingConfig("countryPaging", "code", CountryType / "code")
object CityPaging extends PagingConfig("cityPaging", "id", CityType / "name")

override val selectElaborator = SelectElaborator {
  case (
        QueryType,
        "countries",
        List(Binding("offset", IntValue(off)), Binding("limit", IntValue(lim)))) =>
    CountryPaging.setup(off, lim)

  case (PagedCountryType, "items", Nil) =>
    CountryPaging.elabItems

  case (PagedCountryType, "total", Nil) =>
    CountryPaging.elabTotal

  case (
        CountryType,
        "cities",
        List(Binding("offset", IntValue(off)), Binding("limit", IntValue(lim)))) =>
    CityPaging.setup(off, lim)

  case (PagedCityType, "items", Nil) =>
    CityPaging.elabItems

  case (PagedCityType, "total", Nil) =>
    CityPaging.elabTotal
}

#paging3.text:
case class PagingInfo(
    offset: Option[Int],
    limit: Option[Int],
    hasItems: Boolean,
    itemsAlias: Option[String],
    hasHasMore: Boolean) {
  def elabItems: Elab[Unit] =
    Elab.transformChild { child =>
      val lim0 = if (hasHasMore) limit.map(_ + 1) else limit
      val items = FilterOrderByOffsetLimit(
        None,
        Some(List(OrderSelection(orderTerm, nullsLast = nullsHigh))),
        offset,
        lim0,
        child)
      if (hasHasMore) TransformCursor(genItems, items) else items
    }

  def genItems(c: Cursor): Result[Cursor] = {
    for {
      size <- c.listSize
      elems <- c.asList(Seq)
    } yield {
      if (limit.forall(size <= _)) c
      else ListTransformCursor(c, size - 1, elems.init)
    }
  }

  def elabHasMore: Elab[Unit] =
    Elab
      .addAttribute(countField, Count(Select("items", Select(countAttr))))
      .whenA(!hasItems)

  def genHasMore(c: Cursor): Result[Boolean] =
    if (hasItems) {
      for {
        items <- c.field("items", itemsAlias)
        size <- items.listSize
      } yield limit.exists(size > _)
    } else {
      for {
        num <- c.fieldAs[Long](countField)
      } yield num > offset.getOrElse(0) + limit.getOrElse(num.toInt)
    }
}

