#composed_combine.text:
override def combineAndRun(queries: List[(Query, Cursor)]): F[Result[List[ProtoJson]]] = {
  import SimpleCurrencyQuery.unpackResults

  val expandedQueries =
    queries.map {
      case (Select("currencies", _, child), c @ Code(code)) =>
        (SimpleCurrencyQuery(List(code), child), c)
      case other => other
    }

  if (expandedQueries.sizeCompare(1) <= 0) super.combineAndRun(expandedQueries)
  else {
    val indexedQueries = expandedQueries.zipWithIndex
    val (groupable, ungroupable) = indexedQueries.partition {
      case ((SimpleCurrencyQuery(_, _), _), _) => true
      case _ => false
    }

    def mkKey(q: ((Query, Cursor), String, Int)): (Query, Env, Context) =
      (q._1._1, q._1._2.fullEnv, q._1._2.context)

    val grouped: List[((Query, Cursor), List[Int])] =
      groupable
        .collect {
          case ((SimpleCurrencyQuery(code, child), cursor), i) =>
            ((child, cursor), code, i)
        }
        .groupBy(mkKey)
        .toList
        .map {
          case ((child, _, _), xs) =>
            val (codes, is) = xs.foldLeft((List.empty[String], List.empty[Int])) {
              case ((codes, is), (_, code, i)) => (code :: codes, i :: is)
            }
            val cursor = xs.head._1._2
            ((SimpleCurrencyQuery(codes, child), cursor), is)
        }

    val (grouped0, groupedIndices) = grouped.unzip
    val (ungroupable0, ungroupedIndices) = ungroupable.unzip

    (for {
      groupedResults <- ResultT(super.combineAndRun(grouped0))
      ungroupedResults <- ResultT(super.combineAndRun(ungroupable0))
    } yield {
      val allResults: List[(ProtoJson, Int)] = groupedResults
        .zip(groupedIndices)
        .flatMap((unpackResults _).tupled) ++ ungroupedResults.zip(ungroupedIndices)
      val repackedResults = indexedQueries.map {
        case (_, i) =>
          allResults.find(_._2 == i).map(_._1).getOrElse(ProtoJson.fromJson(Json.Null))
      }

      repackedResults
    }).value
  }
}

object Code {
  def unapply(c: Cursor): Option[String] = c.fieldAs[String]("code").toOption
}

object SimpleCurrencyQuery {
  def apply(codes: List[String], child: Query): Query =
    Environment(Env("countryCodes" -> codes), Select("currencies", child))

  def unapply(sel: Query): Option[(String, Query)] =
    sel match {
      case Environment(env, Select("currencies", None, child)) =>
        env.get[List[String]]("countryCodes").flatMap(_.headOption).map((_, child))
      case _ => None
    }

  def unpackResults(res: ProtoJson, indices: List[Int]): List[(ProtoJson, Int)] =
    res match {
      case j: Json =>
        (for {
          obj <- j.asObject
          fld <- obj("currencies")
          arr <- fld.asArray
        } yield {
          val ress = arr.toList.map { elem =>
            ProtoJson.fromJson(Json.obj("currencies" -> Json.arr(elem)))
          }
          ress.zip(indices)
        }).getOrElse(Nil)
      case _ => Nil
    }
}

#discriminator.text:
lazy val entityTypeDiscriminator = new SqlDiscriminator {
  def discriminate(c: Cursor): Result[Type] = {
    for {
      et <- c.fieldAs[EntityType]("entityType")
    } yield et match {
      case EntityType.Film => FilmType
      case EntityType.Series => SeriesType
    }
  }

  def narrowPredicate(subtpe: Type): Result[Predicate] = {
    def mkPredicate(tpe: EntityType): Result[Predicate] =
      Eql(EType / "entityType", Const(tpe)).success

    subtpe match {
      case FilmType => mkPredicate(EntityType.Film)
      case SeriesType => mkPredicate(EntityType.Series)
      case _ => Result.internalError(s"Invalid discriminator: $subtpe")
    }
  }
}

#unions.text:
object collections extends TableDef("collections") {
  val id = col("id", text)
  val itemType = col("item_type", text)
  val itemA = col("itema", text)
  val itemB = col("itemb", text)
}

val schema =
  schema"""
    type Query {
      collection: [Item!]!
    }
    type ItemA {
      itema: String!
    }
    type ItemB {
      itemb: String!
    }
    union Item = ItemA | ItemB
  """

val QueryType = schema.ref("Query")
val ItemAType = schema.ref("ItemA")
val ItemBType = schema.ref("ItemB")
val ItemType = schema.ref("Item")

val typeMappings =
  List(
    ObjectMapping(
      tpe = QueryType,
      fieldMappings = List(
        SqlObject("collection")
      )
    ),
    SqlUnionMapping(
      tpe = ItemType,
      discriminator = itemTypeDiscriminator,
      fieldMappings = List(
        SqlField("id", collections.id, key = true, hidden = true),
        SqlField("itemType", collections.itemType, discriminator = true, hidden = true)
      )
    ),
    ObjectMapping(
      tpe = ItemAType,
      fieldMappings = List(
        SqlField("id", collections.id, key = true, hidden = true),
        SqlField("itema", collections.itemA)
      )
    ),
    ObjectMapping(
      tpe = ItemBType,
      fieldMappings = List(
        SqlField("id", collections.id, key = true, hidden = true),
        SqlField("itemb", collections.itemB)
      )
    )
  )

object itemTypeDiscriminator extends SqlDiscriminator {
  def discriminate(c: Cursor): Result[Type] =
    for {
      it <- c.fieldAs[String]("itemType")
    } yield it match {
      case "ItemA" => ItemAType
      case "ItemB" => ItemBType
    }

  def narrowPredicate(subtpe: Type): Result[Predicate] = {
    def mkPredicate(tpe: String): Result[Predicate] =
      Eql(ItemType / "itemType", Const(tpe)).success

    subtpe match {
      case ItemAType => mkPredicate("ItemA")
      case ItemBType => mkPredicate("ItemB")
      case _ => Result.internalError(s"Invalid discriminator: $subtpe")
    }
  }
}

