      type Query {
        nested: Nested!
        nestedSum(x: Int!, y: Int!): NestedSum!
      }
      type Nested {
        sum(x: Int!, y: Int!): Int!
        url: String!
        nested: Nested!
      }
      type NestedSum {
        sum: Int!
        nestedSum(x: Int!, y: Int!): NestedSum!
      }
    """

  val QueryType = schema.ref("Query")
  val NestedType = schema.ref("Nested")
  val NestedSumType = schema.ref("NestedSum")

  val typeMappings =
    List(
      ObjectMapping(
        tpe = QueryType,
        fieldMappings = List(
          ValueField[Unit]("nested", _ => ()),
          ValueField[Unit]("nestedSum", _ => ())
        )
      ),
      ObjectMapping(
        tpe = NestedType,
        fieldMappings = List(
          CursorField("sum", sum),
          CursorField("url", url),
          ValueField[Unit]("nested", _ => ())
        )
      ),
      ObjectMapping(
        tpe = NestedSumType,
        fieldMappings = List(
          CursorField("sum", sum),
          ValueField[Unit]("nestedSum", _ => ())
        )
      )
    )

  def sum(c: Cursor): Result[Int] =
    (for {
      x <- c.env[Int]("x")
      y <- c.env[Int]("y")
    } yield x + y).toResult(s"Missing argument")

  def url(c: Cursor): Result[String] = {
    c.env[Boolean]("secure")
      .map(secure => if (secure) "https://localhost/" else "http://localhost/")
      .toResult(s"Missing argument")
  }

  override val selectElaborator = SelectElaborator {
    case (QueryType, "nestedSum", List(Binding("x", IntValue(x)), Binding("y", IntValue(y)))) =>
      Elab.env("x" -> x, "y" -> y)
    case (NestedType, "sum", List(Binding("x", IntValue(x)), Binding("y", IntValue(y)))) =>
      Elab.env("x" -> x, "y" -> y)
    case (
          NestedSumType,
          "nestedSum",
          List(Binding("x", IntValue(x)), Binding("y", IntValue(y)))) =>
      Elab.env("x" -> x, "y" -> y)
  }
}

#value_cursor.text:
case class ValueCursor(
    context: Context,
    focus: Any,
    parent: Option[Cursor],
    env: Env
) extends Cursor {
  def withEnv(env0: Env): Cursor = copy(env = env.add(env0))

  def mkChild(context: Context = context, focus: Any = focus): ValueCursor =
    ValueCursor(context, focus, Some(this), Env.empty)

  def isLeaf: Boolean = false
  def asLeaf: Result[Json] =
    Result.internalError(s"Not a leaf: $tpe")

  def preunique: Result[Cursor] = {
    val listTpe = tpe.nonNull.list
    focus match {
      case _: List[_] => mkChild(context.asType(listTpe), focus).success
      case _ =>
        Result.internalError(s"Expected List type, found $focus for ${listTpe}")
    }
  }

  def isList: Boolean = (tpe, focus) match {
    case (_: ListType, _: List[_]) => true
    case _ => false
  }

  def asList[C](factory: Factory[Cursor, C]): Result[C] = (tpe, focus) match {
    case (ListType(tpe), it: List[_]) =>
      it.view.map(f => mkChild(context.asType(tpe), f)).to(factory).success
    case _ => Result.internalError(s"Expected List type, found $tpe")
  }

  def listSize: Result[Int] = (tpe, focus) match {
    case (ListType(_), it: List[_]) => it.size.success
    case _ => Result.internalError(s"Expected List type, found $tpe")
  }

  def isNullable: Boolean = (tpe, focus) match {
    case (_: NullableType, _: Option[_]) => true
    case _ => false
  }

  def asNullable: Result[Option[Cursor]] = (tpe, focus) match {
    case (NullableType(tpe), o: Option[_]) =>
      o.map(f => mkChild(context.asType(tpe), f)).success
    case (_: NullableType, _) => Result.internalError(s"Found non-nullable $focus for $tpe")
    case _ => Result.internalError(s"Expected Nullable type, found $focus for $tpe")
  }

  def isDefined: Result[Boolean] = (tpe, focus) match {
    case (_: NullableType, opt: Option[_]) => opt.isDefined.success
    case _ => Result.internalError(s"Expected Nullable type, found $focus for $tpe")
  }

  def narrowsTo(subtpe: TypeRef): Result[Boolean] =
    (subtpe <:< tpe &&
      objectMapping(context.asType(subtpe)).exists {
        case ValueObjectMapping(_, _, classTag) =>
          classTag.runtimeClass.isInstance(focus)
        case _ => false
      }).success

  def narrow(subtpe: TypeRef): Result[Cursor] =
    narrowsTo(subtpe).flatMap { n =>
      if (n)
        mkChild(context.asType(subtpe)).success
      else
        Result.internalError(
          s"Focus ${focus} of static type $tpe cannot be narrowed to $subtpe")
    }

  def field(fieldName: String, resultName: Option[String]): Result[Cursor] =
    mkCursorForField(this, fieldName, resultName)
}

#run_value.text:
/**
 * Interpret `query` against `cursor` with expected type `tpe`.
 *
 * If the query is invalid errors will be returned on the left hand side of the result.
 */
def runValue(query: Query, tpe: Type, cursor: Cursor): Result[ProtoJson] = {
  if (!cursorCompatible(tpe, cursor.tpe))
    Result.internalError(s"Mismatched query and cursor type in runValue: $tpe ${cursor.tpe}")
  else {
    (query, tpe.dealias) match {
      case (Environment(childEnv: Env, child: Query), tpe) =>
        runValue(child, tpe, cursor.withEnv(childEnv))

      case (Component(_, _, _), ListType(tpe)) =>
        cursor.asList(Iterator) match {
          case Result.Success(ic) =>
            val builder = Vector.newBuilder[ProtoJson]
            builder.sizeHint(ic.knownSize)
            while (ic.hasNext) {
              val c = ic.next()
              runValue(query, tpe, c) match {
                case Result.Success(v) => builder.addOne(v)
                case notRight => return notRight
              }
            }
            ProtoJson.fromValues(builder.result()).success
          case Result.Warning(ps, _) => Result.Failure(ps)
          case fail @ Result.Failure(_) => fail
          case err @ Result.InternalError(_) => err
        }

      case (Component(mapping, join, child), _) =>
        join(child, cursor).flatMap {
          case Group(conts) =>
            for {
              childName <- resultName(child).toResultOrError(
                "Join child has unexpected shape")
              elems <- conts.traverse {
                case cont =>
                  for {
                    componentName <- resultName(cont).toResultOrError(
                      "Join continuation has unexpected shape")
                  } yield ProtoJson.select(
                    ProtoJson.component(mapping, cont, cursor),
                    componentName
                  )
              }
            } yield ProtoJson.fromDisjointFields(
              List(childName -> ProtoJson.fromValues(elems))
            )

          case cont =>
            for {
              renamedCont <- alignResultName(child, cont).toResultOrError(
                "Join continuation has unexpected shape")
            } yield ProtoJson.component(mapping, renamedCont, cursor)
        }

      case (Unique(child), _) =>
        cursor.preunique.flatMap(c => runList(child, tpe.nonNull, c, true, tpe.isNullable))

      case (_, ListType(tpe)) =>
        runList(query, tpe, cursor, false, false)

      case (TransformCursor(f, child), _) =>
        for {
          ct <- f(cursor)
          value <- runValue(child, tpe, ct)
        } yield value

      case (_, NullableType(tpe)) =>
        cursor
          .asNullable
          .sequence
          .map { rc =>
            for {
              c <- rc
              value <- runValue(query, tpe, c)
            } yield value
          }
          .getOrElse(ProtoJson.fromJson(Json.Null).success)

      case (_, _: ScalarType | _: EnumType) =>
        cursor.asLeaf.map(ProtoJson.fromJson)

      case (_, _: ObjectType | _: InterfaceType | _: UnionType) =>
        runFields(query, tpe, cursor).map(ProtoJson.fromDisjointFields)

      case _ =>
        Result.internalError(s"Stuck at type $tpe for ${query.render}")
    }
  }
}

#complete_all.text:
/**
 * Complete a collection of possibly deferred results.
 *
 * Each result is completed by locating any subtrees which have been deferred or delegated to
 * some other component interpreter in an overall composite interpreter. Deferred subtrees are
 * gathered, grouped by their associated interpreter and then evaluated in batches. The
 * results of these batch evaluations are then completed in a subsequent stage recursively
 * until the results are fully evaluated or yield errors.
 *
 * Complete results are substituted back into the corresponding enclosing Json.
 *
 * Errors are aggregated across all the results and are accumulated on the `Left` of the
 * result.
 */
def completeAll[F[_]: Monad](pjs: List[ProtoJson]): F[Result[List[Json]]] = {
  def gatherDeferred(pj: ProtoJson): List[DeferredJson] = {
    @tailrec
    def loop(pending: Chain[ProtoJson], acc: List[DeferredJson]): List[DeferredJson] =
      pending.uncons match {
        case None => acc
        case Some((hd, tl)) =>
          (hd: @unchecked) match {
            case _: Json => loop(tl, acc)
            case d: DeferredJson => loop(tl, d :: acc)
            case ProtoObject(fields) => loop(Chain.fromSeq(fields.map(_._2)) ++ tl, acc)
            case ProtoArray(elems) => loop(Chain.fromSeq(elems) ++ tl, acc)
            case ProtoSelect(elem, _) => loop(elem +: tl, acc)
          }
      }

    pj match {
      case _: Json => Nil
      case _ => loop(Chain.one(pj), Nil)
    }
  }

  def scatterResults(pj: ProtoJson, subst: mutable.Map[DeferredJson, Json]): Json = {
    def loop(pj: ProtoJson): Json =
      (pj: @unchecked) match {
        case p: Json => p
        case d: DeferredJson => subst(d)
        case ProtoObject(fields) =>
          val fields0 = fields.map { case (label, pvalue) => (label, loop(pvalue)) }
          Json.fromFields(fields0)
        case ProtoArray(elems) =>
          val elems0 = elems.map(loop)
          Json.fromValues(elems0)
        case ProtoSelect(elem, fieldName) =>
          loop(elem).asObject.flatMap(_(fieldName)).getOrElse(Json.Null)
      }

    loop(pj)
  }

  val batchedEffects =
    pjs
      .flatMap(gatherDeferred)
      .asInstanceOf[List[EffectJson[F]]]
      .groupMap(ej => (ej.mapping, ej.handler))(identity)
      .toList

  (for {
    batchedResults <-
      batchedEffects.traverse {
        case ((mapping, handler), batch) =>
          val queries = batch.map(e => (e.query, e.cursor))
          for {
            pnext <-
              handler match {
                case None =>
                  ResultT(mapping.combineAndRun(queries))
                case Some(handler) =>
                  for {
                    cs <- ResultT(handler.runEffects(queries))
                    conts <- ResultT(
                      queries
                        .traverse {
                          case (q, _) =>
                            Query
                              .extractChild(q)
                              .toResultOrError("Continuation query has the wrong shape")
                        }
                        .pure[F])
                    res <- ResultT(combineResults((conts, cs).parMapN {
                      case (query, cursor) =>
                        mapping.interpreter.runValue(query, cursor.tpe, cursor)
                    }).pure[F])
                  } yield res
              }
            next <- ResultT(completeAll[F](pnext))
          } yield batch.zip(next)
      }
  } yield {
    val subst = {
      val m = new java.util.IdentityHashMap[DeferredJson, Json]
      Monoid.combineAll(batchedResults).foreach { case (d, j) => m.put(d, j) }
      m.asScala
    }
    pjs.map(pj => scatterResults(pj, subst))
  }).value
}

#composed_base.text:
abstract class ComposedMapping[F[_]](implicit val M: MonadThrow[F]) extends Mapping[F] {
  override def mkCursorForMappedField(
      parent: Cursor,
      fieldContext: Context,
      fm: FieldMapping): Result[Cursor] =
    ComposedCursor(fieldContext, parent.env).success

  case class ComposedCursor(context: Context, env: Env) extends AbstractCursor {
    val focus = null
    val parent = None

    def withEnv(env0: Env): Cursor = copy(env = env.add(env0))

    override def field(fieldName: String, resultName: Option[String]): Result[Cursor] =
      mkCursorForField(this, fieldName, resultName)
  }
}

