      l <- c.asLeaf
    } yield l
  assertEquals(i, Result.Success(Json.fromInt(23)))

  val s =
    for {
      c <- CursorBuilder[String].build(Context(StringType), "foo")
      _ = assert(c.isLeaf)
      l <- c.asLeaf
