  val f =
    for {
      c <- CursorBuilder[Double].build(Context(FloatType), 13.0)
      _ = assert(c.isLeaf)
      l <- c.asLeaf
    } yield l
  assertEquals(f, Result.Success(Json.fromDouble(13.0).get))
}

