#preserve_args.text:
object PreserveArgsElaborator extends SelectElaborator {
  case class Preserved(args: List[Binding], directives: List[Directive])

  def subst(query: Query, fieldName: String, preserved: Preserved): Query = {
    def loop(query: Query): Query =
      query match {
        case Select(`fieldName`, alias, child) =>
          UntypedSelect(
            fieldName,
            alias,
            preserved.args,
            directives = preserved.directives,
            child)
        case Environment(env, child) if env.contains("preserved") => loop(child)
        case e @ Environment(_, child) => e.copy(child = loop(child))
        case g: Group => g.copy(queries = g.queries.map(loop))
        case t @ TransformCursor(_, child) => t.copy(child = loop(child))
        case other => other
      }

    loop(query)
  }

  override def transform(query: Query): Elab[Query] = {
    query match {
      case UntypedSelect(fieldName, _, _, _, _) =>
        for {
          t <- super.transform(query)
          preserved <- Elab.envE[Preserved]("preserved")
        } yield subst(t, fieldName, preserved)

      case other => super.transform(other)
    }
  }

  def select(
      ref: TypeRef,
      name: String,
      args: List[Binding],
      directives: List[Directive]): Elab[Unit] =
    Elab.env("preserved", Preserved(args, directives))
}

#subscription_mapping.text:
def mapping(ref: SignallingRef[IO, Int]): Mapping[IO] =
  new ValueMapping[IO] {

    val schema: Schema =
      schema"""
        type Query {
          get: Int!
        }
        type Mutation {
          put(n: Int): Int!
        }
        type Subscription {
          watch: Int!
        }
      """

    val QueryType = schema.ref("Query")
    val MutationType = schema.ref("Mutation")
    val SubscriptionType = schema.ref("Subscription")

    val typeMappings =
      List(
        ObjectMapping(
          QueryType,
          List(
            RootEffect.computeCursor("get")((path, env) =>
              ref.get.map(n => Result(valueCursor(path, env, n))))
          )),
        ObjectMapping(
          MutationType,
          List(
            RootEffect.computeCursor("put")((path, env) =>
              env.get[Int]("n") match {
                case None =>
                  Result.failure(s"Implementation error: `n: Int` not found in $env").pure[IO]
                case Some(n) => ref.set(n).map(_ => Result(valueCursor(path, env, n)))
              })
          )
        ),
        ObjectMapping(
          SubscriptionType,
          List(
            RootStream.computeCursor("watch")((path, env) =>
              ref.discrete.map(n => Result(valueCursor(path, env, n))))
          ))
      )

    override val selectElaborator: SelectElaborator =
      SelectElaborator {
        case (MutationType, "put", List(Query.Binding("n", Value.IntValue(n)))) =>
          Elab.env("n" -> n)
      }
  }
